window.KCFuturaBundledSearchCatalog=[{"kind":"training","module":"quick","targetIndex":0,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":1,"title":"Kapitel 1 · Überblick über die Oberfläche des Bilderrechners","text":"Bevor wir den ersten Verkauf durchführen, sehen wir uns gemeinsam die Oberfläche des KC Bilderrechners an. Wir gehen dabei von oben nach unten vor. Welcher Bereich befindet sich rechts in der Oberfläche des Bilderrechners? Die Warengruppen Der Warenkorb Nur das Vereinslogo Die Artikelbilder Der Warenkorb befindet sich rechts. Dort werden die ausgewählten Artikel, Mengen und Summen angezeigt.","tip":"Zuerst Orientierung, danach Bedienung: So findest du später jede Funktion schneller."},{"kind":"training","module":"quick","targetIndex":1,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":2,"title":"Kapitel 2 · Kopfzeile und Statusanzeigen","text":"Die Kopfzeile ist die wichtigste Informationszeile am oberen Bildschirmrand. Prüfe dort vor Arbeitsbeginn und beim Schichtwechsel den angemeldeten Bediener, die Kassenbezeichnung und den Betriebszustand. Außerdem findest du dort Version, Datum, Uhrzeit sowie Bedienelemente für Sperre, Ton, Menü und Programmende. Was solltest du in der Kopfzeile besonders beim Schichtwechsel kontrollieren? Nur die Uhrzeit Den angemeldeten Bediener und den Betriebszustand Den Preis des letzten Artikels Die Anzahl der Warengruppen Beim Schichtwechsel müssen vor allem der angemeldete Bediener und der richtige Betriebszustand kontrolliert werden.","tip":"Merksatz: Arbeite niemals unter dem Namen eines anderen Bedieners und kontrolliere vor dem ersten Verkauf den richtigen Betriebszustand."},{"kind":"training","module":"quick","targetIndex":2,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":3,"title":"Kapitel 3 · Bediener- und Moduszeile","text":"Unter der Kopfzeile findest du den Bediener, die Artikelsuche, Trainingsmodus, Stoßzeiten, Happy Hour und die Meldungsanzeige. Welcher Modus darf keine echten Umsätze erzeugen? Normalbetrieb Trainingsmodus Stoßzeitenmodus Happy Hour Im Trainingsmodus werden Übungsvorgänge getrennt behandelt und dürfen nicht in den normalen Umsatz einfließen.","tip":"Vor einem echten Verkauf muss klar erkennbar sein, welcher Bediener und welcher Modus aktiv sind."},{"kind":"training","module":"quick","targetIndex":3,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":4,"title":"Kapitel 4 · Warengruppen und Artikelbuttons","text":"Die Warengruppen bestimmen, welche Artikel angezeigt werden. Ein Artikelbutton zeigt Name, Bild und Preis. Zusätzliche Zeichen führen zu Informationen, Varianten oder Happy-Hour-Preisen. Wofür steht das Pluszeichen auf einem Artikelbutton? Menge sofort verdoppeln Varianten oder Zusätze öffnen Artikel löschen Happy Hour einschalten Das Pluszeichen öffnet die Varianten- oder Zusatzauswahl des Artikels.","tip":"Die große Artikelfläche verkauft den Standardartikel. Das Pluszeichen öffnet Varianten."},{"kind":"training","module":"quick","targetIndex":4,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":5,"title":"Kapitel 5 · Warenkorb und Mengensteuerung","text":"Im Warenkorb siehst du alle gewählten Artikel. Mengen lassen sich oben oder direkt in der Artikelzeile ändern. Einzelne Positionen und der komplette offene Warenkorb können getrennt gelöscht werden. Welcher Mülleimer löscht nur einen einzelnen Artikel? Der Mülleimer in der betreffenden Warenkorbzeile Die Taste Warenkorb löschen Die Taste Mehr Der Zurückpfeil Der Mülleimer direkt in der Warenkorbzeile entfernt nur diese Position.","tip":"Achte darauf, ob du nur eine Position oder den gesamten offenen Warenkorb löschen möchtest."},{"kind":"training","module":"quick","targetIndex":5,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":6,"title":"Kapitel 6 · Zahlungs- und Rückgeldbereich","text":"Im Zahlungsbereich werden Scheine und Münzen erfasst. Die Kasse zeigt gegebenen Betrag, offenen Betrag und Rückgeld. Bezahlt werden kann passend, über Stimmt so, bar oder über freigegebene QR- und Kartenfunktionen. Was bedeutet „Stimmt so“? Der Warenkorb wird gelöscht Der Kunde erhält den vollen Zahlbetrag zurück Der eingegebene Mehrbetrag wird als Trinkgeld behandelt Die Zahlung wird auf später verschoben Bei „Stimmt so“ wird der über dem Rechnungsbetrag liegende Zahlbetrag als Trinkgeld erfasst.","tip":"Rückgeld immer kontrollieren und laut nennen, bevor der Vorgang abgeschlossen wird."},{"kind":"training","module":"quick","targetIndex":6,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":7,"title":"Kapitel 7 · Sondertasten","text":"Unterhalb des Zahlungsbereichs befinden sich Sondertasten wie Personal, Pfandrückgabe, Trinkgeld, Reklamation, Bon und Mehr. Sie werden nur für besondere Vorgänge verwendet. Wofür dient die Taste Personal? Für einen normalen Barverkauf Für Personalbeköstigung als eigene Buchungsart Für den Gesamtrabatt Zum Öffnen des Menüs Personal erfasst Personalbeköstigung als eigene Buchungsart und ist kein normaler Rabattverkauf.","tip":"Sondertasten nicht mit normalen Verkaufsartikeln oder Rabatten verwechseln."},{"kind":"training","module":"quick","targetIndex":7,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":8,"title":"Kapitel 8 · Einzelartikel verkaufen","text":"Ich wähle einen einzelnen Artikel über seine große Artikeltaste aus. Der Artikel erscheint sofort im Warenkorb. Danach wird die Barzahlung gestartet und der Vorgang abgeschlossen. Wo tippst du für den Verkauf eines Standardartikels? Auf die große Artikelfläche Immer auf das Pluszeichen Auf den Mülleimer Auf die Uhrzeit Ein Standardartikel wird über seine große Artikelfläche ausgewählt. Das Pluszeichen ist für Varianten und Zusätze vorgesehen.","tip":"Für den Standardartikel immer die große Artikelfläche verwenden. Das Pluszeichen ist ausschließlich für Varianten gedacht."},{"kind":"training","module":"quick","targetIndex":8,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":9,"title":"Kapitel 9 · Mehrere Artikel und verschiedene Warengruppen","text":"Jetzt werden mehrere Artikel nacheinander ausgewählt, auch aus unterschiedlichen Warengruppen. Mehrfaches Antippen einer Artikeltaste erhöht die Menge dieses Artikels. Was bewirkt mehrfaches Antippen derselben Artikeltaste? Die Menge dieses Artikels wird erhöht Der Artikel wird gelöscht Die Kasse wird gesperrt Die Warengruppe wird geschlossen Mehrfaches Antippen derselben Artikeltaste erhöht die Menge dieses Artikels im Warenkorb.","tip":"Vor dem Bezahlen immer Artikel, Mengen und Gesamtsumme kontrollieren."},{"kind":"training","module":"quick","targetIndex":9,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":10,"title":"Kapitel 10 · Mengen im Warenkorb ändern","text":"Eine Menge kann durch mehrfaches Antippen der Artikeltaste, über die Mengenknöpfe im Kopf des Warenkorbs und direkt in der jeweiligen Artikelzeile geändert werden. Was muss vor einer Mengenänderung in der Artikelzeile geprüft werden? Ob die richtige Warenkorbzeile ausgewählt ist Ob die Uhr richtig geht Ob der Ton ausgeschaltet ist Ob das Logo sichtbar ist Vor der Mengenänderung muss die richtige Warenkorbzeile ausgewählt beziehungsweise eindeutig zugeordnet sein.","tip":"Zuerst die richtige Warenkorbzeile markieren und danach die gewünschte Mengensteuerung verwenden."},{"kind":"training","module":"quick","targetIndex":10,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":11,"title":"Kapitel 11 · Artikel oder gesamten Warenkorb löschen","text":"Ein einzelner Artikel wird über das Mülleimersymbol seiner Warenkorbzeile entfernt. Der komplette offene Warenkorb kann über Warenkorb löschen geleert werden. Wie entfernst du nur eine einzelne offene Position? Mit dem Mülleimer in ihrer Warenkorbzeile Mit Warenkorb löschen Durch Programmende Mit der Personaltaste Nur der Mülleimer in der betreffenden Warenkorbzeile entfernt diese einzelne offene Position.","tip":"Ein Löschen ersetzt niemals eine Reklamation eines bereits abgeschlossenen Verkaufs."},{"kind":"training","module":"quick","targetIndex":11,"part":"Teil 1","section":"Grundlagen und Verkauf","chapter":12,"title":"Kapitel 12 · Warenkorb bezahlen und Rückgeld","text":"Nach der Kontrolle wird der erhaltene Barbetrag über Scheine oder Münzen eingegeben. Die Kasse zeigt Zahlbetrag und Rückgeld. Was ist vor dem endgültigen Abschluss einer Barzahlung zu tun? Rückgeld kontrollieren und laut nennen Den Warenkorb ungesehen löschen Die Kasse neu laden Die Warengruppe wechseln Vor dem Abschluss wird das angezeigte Rückgeld kontrolliert und dem Gast laut genannt.","tip":"Das angezeigte Rückgeld laut nennen und erst danach den Vorgang abschließen."},{"kind":"training","module":"advanced","targetIndex":0,"part":"Teil 1","section":"Sonderfunktionen","chapter":1,"title":"Kapitel 7 · Trinkgeld vollständig erfassen","text":"Trinkgeld kann auf mehreren Wegen erfasst werden. Nach Eingabe des erhaltenen Geldbetrags kann Stimmt so verwendet werden. Über Aufrunden wird ein Zielbetrag gewählt. Nachträgliches Trinkgeld wird über die Trinkgeldtaste und eine Betragsauswahl gebucht. Das Trinkgeld wird im Abschluss getrennt vom Warenumsatz ausgewiesen. Wann darf „Stimmt so“ verwendet werden? Vor Eingabe des erhaltenen Geldbetrags Erst nach Eingabe des erhaltenen Geldbetrags Nur beim Kartenzahlen Nie „Stimmt so“ wird erst nach Erfassung des erhaltenen Zahlbetrags verwendet.","tip":"Stimmt so erst nach Erfassung des erhaltenen Zahlbetrags verwenden. Trinkgeld niemals als normalen Verkaufsartikel buchen."},{"kind":"training","module":"advanced","targetIndex":1,"part":"Teil 1","section":"Sonderfunktionen","chapter":2,"title":"Kapitel 8 · Buchung auf ein Personen- oder Organisationskonto","text":"Organisationen oder berechtigte Personen können Waren auf Rechnung erhalten. Die ausgewählten Artikel werden einem Konto zugeordnet und dort zu einem späteren Rechnungsbetrag summiert. Dieses Kapitel ist in der Schulungsstruktur vorbereitet. Die vorliegende Stand-alone-Kasse besitzt jedoch noch keine freigegebene vollständige Kontobuchungsoberfläche. Wann darf die Kontobuchung praktisch verwendet werden? Immer sofort Erst wenn Kontoauswahl, Berechtigung und Abrechnung freigegeben sind Nur ohne Berechtigung Nur im Trainingsmodus Die Kontobuchung darf erst nach vollständiger Freigabe aller notwendigen Funktionen verwendet werden.","tip":"Kontobuchungen dürfen erst praktisch geschult werden, wenn Kontoauswahl, Berechtigung, Sammelrechnung und Abschluss im Bilderrechner freigegeben sind."},{"kind":"training","module":"advanced","targetIndex":2,"part":"Teil 1","section":"Sonderfunktionen","chapter":3,"title":"Kapitel 9 · Personalbeköstigung verbuchen","text":"Zuerst wird der Artikel mit der richtigen Menge in den Warenkorb gelegt. Statt über Bezahlen wird der Vorgang über Personal verbucht. Dadurch wird die Ware als Personalbeköstigung erfasst, ohne eine personenbezogene Einzelzuordnung vorzunehmen. Wie wird Personalbeköstigung korrekt abgeschlossen? Über Bezahlen Über die Taste Personal Als Rabatt Durch Löschen Personalbeköstigung wird über die eigene Taste Personal verbucht.","tip":"Personal ist eine eigene Buchungsart und kein Rabattverkauf."},{"kind":"training","module":"advanced","targetIndex":3,"part":"Teil 1","section":"Sonderfunktionen","chapter":4,"title":"Kapitel 10 · Pfandverkauf, Pfandrückgabe und Auszahlung","text":"Pfandaufschläge sind bei den entsprechenden Verkaufsartikeln bereits enthalten. Bei der Rückgabe wird in der Warengruppe Pfand der passende Rückgabeartikel und die Menge gewählt. Verkaufsartikel und Rückgaben können im selben Warenkorb verrechnet werden. Entsteht ein negativer Gesamtbetrag, zeigt die Kasse Auszahlung und der Bezahlknopf ändert seinen Zustand. Glas und Feuerzange können einzeln oder gemeinsam zurückgegeben werden. Was muss bei einer Pfandrückgabe geprüft werden? Nur die Uhrzeit Pfandart und tatsächliche Rückgabemenge Nur der Bedienername Nur der Ton Pfandart und Menge müssen mit den tatsächlich zurückgegebenen Gegenständen übereinstimmen.","tip":"Pfandart und Rückgabemenge immer genau mit den tatsächlich abgegebenen Gegenständen abgleichen."},{"kind":"training","module":"advanced","targetIndex":4,"part":"Teil 1","section":"Sonderfunktionen","chapter":5,"title":"Kapitel 11 · Artikelinformationen und Allergene","text":"Oben rechts auf entsprechend vorbereiteten Artikeltasten befindet sich die Infotaste. Der erste Klick öffnet eine Schnellübersicht mit Allergenen und wichtigen Hinweisen. Über Weitere Informationen werden zusätzliche Angaben wie Zutaten und Nährwerte angezeigt. Wie werden Fragen zu Allergenen beantwortet? Nach Vermutung Nur anhand der hinterlegten Informationen Mit einer privaten Internetrecherche Gar nicht Bei Allergenen dürfen ausschließlich die hinterlegten Informationen verwendet werden.","tip":"Bei Allergenen und Inhaltsstoffen ausschließlich die hinterlegten Informationen verwenden und niemals raten."},{"kind":"training","module":"advanced","targetIndex":5,"part":"Teil 1","section":"Sonderfunktionen","chapter":6,"title":"Kapitel 12 · Varianten über das Pluszeichen auswählen","text":"Das Pluszeichen auf einer Artikeltaste öffnet die zugehörigen Varianten. Dort kann die gewünschte Ausführung gewählt werden. Varianten können alternativ auch zusammen mit dem Hauptartikel auf einer eigenen gemeinsamen Auswahltaste angeboten werden. Wofür steht das Pluszeichen? Standardartikel sofort verkaufen Varianten oder Zusätze öffnen Artikel löschen Kasse sperren Das Pluszeichen öffnet Varianten oder Zusätze.","tip":"Große Artikelfläche bedeutet Standardartikel; Pluszeichen bedeutet Varianten- oder Zusatzauswahl."},{"kind":"training","module":"advanced","targetIndex":6,"part":"Teil 1","section":"Sonderfunktionen","chapter":7,"title":"Kapitel 13 · Favoriten und meistverkaufte Artikel","text":"Goldene Sterne oben rechts kennzeichnen Favoriten beziehungsweise häufig verkaufte Artikel. Diese Artikel werden zusätzlich in der eigenen Warengruppe Favoriten gesammelt und können dort besonders schnell ausgewählt werden. Was kennzeichnet der goldene Stern? Einen gelöschten Artikel Favoriten oder häufig verkaufte Artikel Pfandartikel Reklamationen Der goldene Stern kennzeichnet Favoriten beziehungsweise häufig verkaufte Artikel.","tip":"Der Stern ist eine Orientierungshilfe. Artikelname und Preis trotzdem vor dem Antippen prüfen."},{"kind":"training","module":"advanced","targetIndex":7,"part":"Teil 1","section":"Sonderfunktionen","chapter":8,"title":"Kapitel 14 · Pool- und Kombinationsartikel","text":"Bei Pool- oder Kombinationsartikeln liegen häufig gemeinsam verkaufte Produkte auf einer gemeinsamen Artikeltaste. Ein Klick legt beide Bestandteile sofort in den Warenkorb, dort werden sie weiterhin einzeln angezeigt. Für eine Kombination kann ein eigener Gesamtpreis hinterlegt sein. Was ist bei einem Kombinationsartikel zu kontrollieren? Nur das Bild Alle Bestandteile und der Kombinationspreis Nur die Uhrzeit Nur die Warengruppe Im Warenkorb müssen alle Bestandteile und der vorgesehene Kombinationspreis geprüft werden.","tip":"Im Warenkorb kontrollieren, ob alle Bestandteile und der vorgesehene Kombinationspreis korrekt übernommen wurden."},{"kind":"training","module":"advanced","targetIndex":8,"part":"Teil 1","section":"Sonderfunktionen","chapter":9,"title":"Kapitel 15 · Happy Hour und zeitabhängige Sonderpreise","text":"Für einen definierten Zeitraum kann ein Happy-Hour-Preis gelten. Innerhalb dieses Zeitfensters wird automatisch der hinterlegte Sonderpreis berechnet. Im Warenkorb sollen Standardpreis und Happy-Hour-Preis nachvollziehbar ausgewiesen werden. Dieses Kapitel ist vorbereitet, bis Zeitregel, Preisanzeige und Abrechnung vollständig freigegeben sind. Was muss bei Happy Hour sichtbar kontrollierbar sein? Nur das Logo Beginn, Ende und Preiskennzeichnung Nur der Ton Nur der Bediener Beginn, Ende und die sichtbare Preiskennzeichnung müssen kontrollierbar sein.","tip":"Der Bediener muss Beginn, Ende und sichtbare Preiskennzeichnung kontrollieren können."},{"kind":"training","module":"advanced","targetIndex":9,"part":"Teil 1","section":"Sonderfunktionen","chapter":10,"title":"Kapitel 16 · Reklamation als vollständiger Vorgang","text":"Eine Reklamation wird in einem einzigen zusammenhängenden Ablauf bearbeitet: Reklamation öffnen, Artikel und Menge erfassen, Grund auswählen, Bonbezug und Betrag prüfen, Notiz ergänzen und speichern. Was ersetzt keine Reklamation? Ein vollständiger Reklamationsablauf Das Löschen eines offenen Warenkorbs Die Auswahl eines Grundes Eine Notiz Das Löschen eines offenen Warenkorbs ersetzt niemals eine Reklamation.","tip":"Eine Reklamation niemals durch Löschen eines offenen Warenkorbs ersetzen."},{"kind":"training","module":"advanced","targetIndex":10,"part":"Teil 1","section":"Sonderfunktionen","chapter":11,"title":"Kapitel 17 · Trainingsmodus sicher verwenden","text":"Der Trainingsmodus kann im Normalbetrieb jederzeit ein- und wieder ausgeschaltet werden. Nach dem Einschalten verändert sich die Darstellung deutlich und in der Summen- beziehungsweise Statusanzeige wird der Trainingsmodus kenntlich gemacht. Alle in diesem Modus erfassten Artikel und abgeschlossenen Vorgänge werden getrennt als Trainingsvorgänge gespeichert und fließen nicht in den normalen Buchungslauf ein. Dadurch können Bediener direkt an der Originaloberfläche üben, ohne echte Umsätze zu erzeugen. Im Stoßzeitenmodus steht das Training bewusst nicht zur Verfügung. Was gilt vor einem echten Verkauf? Trainingsmodus muss ausgeschaltet sein Trainingsmodus muss aktiv bleiben Stoßzeitenmodus muss aus sein Ton muss aus sein Vor einem echten Verkauf muss der Trainingsmodus wieder ausgeschaltet sein.","tip":"Vor Beginn immer prüfen, ob der Trainingsmodus sichtbar aktiv ist. Vor dem echten Verkauf muss er wieder ausgeschaltet sein."},{"kind":"training","module":"advanced","targetIndex":11,"part":"Teil 1","section":"Sonderfunktionen","chapter":12,"title":"Kapitel 18 · Stoßzeitenmodus für schnellen und sicheren Verkauf","text":"Bei starkem Andrang wird der Stoßzeitenmodus über die Taste Stoßzeiten eingeschaltet. Die Hintergrunddarstellung wechselt, Artikeltasten werden größer und weniger wichtige Sonderfunktionen werden ausgeblendet. Dadurch bleibt die Oberfläche ruhig, übersichtlich und auf die häufigsten Verkaufsschritte konzentriert. Personal- und weitere Sondertasten können in diesem Modus entfallen. Ein aktiver Trainingsmodus ist während Stoßzeiten nicht zulässig. Durch erneutes Antippen der Taste Stoßzeiten kehrt der KC Bilderrechner in den Normalmodus zurück; die ursprünglichen Tastengrößen und ausgeblendeten Funktionen erscheinen wieder. Happy Hour und Stoßzeiten dürfen gleichzeitig aktiv sein. Wann wird der Stoßzeitenmodus verwendet? Immer dauerhaft Bei starkem Andrang und danach wieder ausgeschaltet Nur für Reklamationen Nur ohne Artikel Der Stoßzeitenmodus wird bei starkem Andrang aktiviert und danach wieder beendet.","tip":"Stoßzeiten nur bei Bedarf aktivieren und nach Ende des Andrangs wieder in den Normalbetrieb wechseln."},{"kind":"training","module":"advanced","targetIndex":12,"part":"Teil 1","section":"Sonderfunktionen","chapter":13,"title":"Kapitel 19 · Scanner-Bedienung und Bedienerzuordnung","text":"Ein Bluetooth-Barcodescanner wird im HID-Modus mit dem Tablet gekoppelt und verhält sich wie eine Tastatur. Die Artikelnummer eines Artikels ist in einem QR-Code gespeichert. Beim Scannen wird der Artikel sofort in den Warenkorb übernommen; wiederholtes Scannen erhöht die Menge. QR-Codes können direkt am Artikel oder gut erreichbar in seiner Nähe angebracht werden, sodass der Artikel bereits während des Zapfens oder Ausgebens per Finger- oder Uhrscanner erfasst werden kann. Der Vorgang wird anschließend wie gewohnt über Bar abgeschlossen oder – sofern eingerichtet – durch Scannen des Zahlungs-QR-Codes. Für eine Bedienerzuordnung wird vor dem Verkauf kurz der persönliche Mitarbeitercode gescannt. Dieser Bediener bleibt aktiv, bis sich eine andere Person über die Bedienertaste oder ihren QR-Code anmeldet. Was ist vor dem Verkauf mit Scanner zu kontrollieren? Die angezeigte Bedienerzuordnung Nur die Lautstärke Nur das Datum Nur die Farbe des QR-Codes Vor dem Verkauf muss die angezeigte Bedienerzuordnung kontrolliert werden.","tip":"Scanner im HID-Modus koppeln, Codes eindeutig beschriften und vor dem Verkauf die angezeigte Bedienerzuordnung kontrollieren."},{"kind":"training","module":"practice","targetIndex":0,"part":"Teil 1","section":"Praxisprüfung","chapter":1,"title":"Einfacher Verkauf","text":"Verkaufe einen Glühwein rot und starte die Zahlung.","tip":""},{"kind":"training","module":"practice","targetIndex":1,"part":"Teil 1","section":"Praxisprüfung","chapter":2,"title":"Reklamation","text":"Öffne den Reklamationsablauf.","tip":""},{"kind":"training","module":"practice","targetIndex":2,"part":"Teil 1","section":"Praxisprüfung","chapter":3,"title":"Pfandrückgabe","text":"Öffne die Pfandrückgabe und erfasse eine Glasrückgabe.","tip":""},{"kind":"academy","module":"reklamation","part":"Teil 2","section":"Folge 1","chapter":1,"title":"Reklamationsmanagement","text":"Aus einer Reklamation einen zufriedenen Gast machen. ruhig reagieren, die Wirkung verstehen, passende Lösungen finden und den KC Bilderrechner als Unterstützung kennen laura marc herr_becker frau_schmitt lukas Laura Herzlich willkommen, Teilnehmer. Heute lernst du, wie du Reklamationen ruhig, freundlich und lösungsorientiert behandelst. Herr Becker Guten Abend. Mein gerade erhaltener Glühwein ist leider nur noch lauwarm. Wie reagierst du am besten? Das kann eigentlich nicht sein. Einen Moment bitte. Ich kümmere mich sofort darum. Dann müssen Sie ihn schneller trinken. Sehr gut. Du hörst zu, nimmst den Gast ernst und bietest eine Lösung an. Vielen Dank. Der Mitarbeiter blieb ruhig und hat mir einen neuen heißen Glühwein angeboten. So einen freundlichen Service merkt man sich. Marc Reklamationen gehören zum Alltag. Entscheidend ist, dass wir ruhig und professionell reagieren. Lukas Ich habe einen Apfelpunsch bestellt und schon einen Schluck getrunken. Jetzt sehe ich rote Lippenstiftreste am Glas. Wie sollte das Team reagieren? Das Glas nur kurz abwischen. Sich entschuldigen, das Glas sofort austauschen und das beanstandete Glas zum Spülen geben. Erklären, dass der Lippenstift bestimmt vom Gast selbst stammt. Richtig. Eine hygienische Reklamation wird ohne Diskussion ernst genommen und sofort sauber gelöst. So etwas kann passieren. Entscheidend war für mich, dass das Glas sofort ausgetauscht und meine Reklamation freundlich behandelt wurde. Marc Der KC Bilderrechner unterstützt dich bei einer professionellen Reklamationsbearbeitung. Unter dem Warenkorb findest du den Button Reklamation. Wo findest du im KC Bilderrechner die Funktion Reklamation? Unter dem Warenkorb über den Button Reklamation. In der Kopfzeile hinter der Uhr. Nur im PC-Manager. Richtig. Die Funktion Reklamation befindet sich unter dem Warenkorb. Eine klar geführte Reklamation hilft dem Team, ruhig, nachvollziehbar und einheitlich zu handeln. Herr Becker Ich glaube, ich habe statt Feuerzangenbowle einen normalen Glühwein bekommen. Was ist jetzt der richtige erste Schritt? Bestellung und erfasste Positionen ruhig prüfen. Dem Gast widersprechen. Die Reklamation ignorieren. Richtig. Erst prüfen, dann freundlich korrigieren. Obwohl der Stand voll war, wurde meine Bestellung ruhig geprüft. Der Fehler war schnell behoben und ich komme gern wieder. Frau Schmitt Ich habe es heute sehr eilig und beim Überreichen ist Kartoffelcreme auf meinem Mantel gelandet. Welche Reaktion wirkt professionell? Sofort entschuldigen, ruhig helfen und eine Lösung anbieten. Erklären, dass der Gast selbst schuld ist. So tun, als sei nichts passiert. Genau. Nicht die Schuldfrage, sondern Hilfe und ein respektvoller Umgang stehen zuerst im Mittelpunkt. Natürlich habe ich mich geärgert. Aber die ehrliche Entschuldigung und die schnelle Hilfe haben mir gezeigt, dass ich ernst genommen werde. Laura Teilnehmer, das hast du gut gemacht. Du hast verstanden: zuhören, ernst nehmen, prüfen und eine faire Lösung finden.","tip":"Eine Reklamation ist keine Kritik an deiner Person. Erst zuhören, dann entschuldigen und eine passende Lösung anbieten. Im geöffneten Reklamationsfenster werden Artikel, Reklamationsgrund, Belegstatus und Speichern klar geführt. Den genauen Ablauf übst du in der KC Bilderrechner-Schulung."},{"kind":"academy","module":"jugend","part":"Teil 2","section":"Folge 2","chapter":2,"title":"Jugendschutz","text":"Freundlich kontrollieren und gesetzliche Verantwortung übernehmen. gesetzliche Altersgrenzen einordnen, freundlich nach dem Ausweis fragen und bei fehlendem Nachweis sicher handeln laura marc lukas Laura Hallo Teilnehmer. In dieser Folge geht es um den Jugendschutz. Wir schützen junge Menschen und halten eine gesetzliche Vorgabe ein. Marc Die Altersgrenzen stehen in Paragraph 9 des Jugendschutzgesetzes. Das ist keine Regel des Köcheclubs, sondern geltendes Recht. Lukas Hallo. Ich hätte gern einen Glühwein mit Rum. Lukas wirkt jung. Wie reagierst du richtig? Ich schenke sofort aus. Ich frage freundlich nach einem amtlichen Altersnachweis. Ich lehne den Verkauf ohne Erklärung ab. Richtig. Eine freundliche Alterskontrolle ist sachlich, respektvoll und schützt alle Beteiligten. Gestern musste ich tatsächlich meinen Personalausweis zeigen. Erst fand ich das ungewohnt. Aber wenn man darüber nachdenkt, ist es genau richtig. Lukas Ich habe meinen Ausweis heute leider nicht dabei. Aber ich bin wirklich schon achtzehn. Was ist ohne sicheren Altersnachweis richtig? Ausnahmsweise verkaufen. Keinen alkoholischen Artikel mit Rum abgeben und eine alkoholfreie Alternative anbieten. Nur die Hälfte ausschenken. Richtig. Ohne verlässlichen Nachweis wird kein altersbeschränkter Artikel abgegeben. Das ist zwar schade, aber ich verstehe die Entscheidung. Ein alkoholfreier Punsch ist für heute auch in Ordnung. Laura Teilnehmer, warum ist Jugendschutz keine Sonderregel des Köcheclubs? Welche Aussage stimmt? Die Altersgrenzen beruhen auf dem Jugendschutzgesetz. Der Köcheclub legt sie jedes Jahr neu fest. Sie gelten nur bei großem Besucherandrang. Genau. Die gesetzlichen Altersgrenzen gelten unabhängig vom Köcheclub und müssen eingehalten werden. Eine höfliche Kontrolle zeigt Verantwortung und schützt junge Menschen. Laura Teilnehmer, sehr gut. Du weißt jetzt, wie du freundlich kontrollierst und sicher entscheidest.","tip":"Frage klar und freundlich nach einem amtlichen Altersnachweis. Du musst dich dafür nicht entschuldigen."},{"kind":"academy","module":"konflikt","part":"Teil 2","section":"Folge 3","chapter":3,"title":"Konfliktmanagement","text":"Probleme ansprechen, Hintergründe verstehen und gemeinsam Lösungen finden. Vorwürfe vermeiden, zuhören, Ich-Botschaften nutzen, Aufgaben fair verteilen und Absprachen treffen laura marc michael sabrina Laura Hallo Teilnehmer. Konflikte entstehen oft nicht aus bösem Willen, sondern weil Informationen fehlen oder Belastungen unterschiedlich wahrgenommen werden. Michael Sabrina, warum musstest du gestern ausgerechnet im dicksten Geschäft eine Zigarettenpause machen? Wie kann Michael das Gespräch besser beginnen? Du lässt uns immer hängen. Gestern war viel los. Ich habe mich überfordert gefühlt. Was war bei dir los? Darüber brauchen wir gar nicht mehr zu reden. Richtig. Eine Ich-Botschaft beschreibt die eigene Wahrnehmung und öffnet das Gespräch. Mir ging es gestern nicht gut und ich brauchte kurz Luft. Danke, dass du nachfragst, statt sofort zu urteilen. Sabrina Michael, ich habe das Gefühl, dass ich fast immer spüle und aufräume. Ich möchte auch einmal vorne verkaufen. Welche Lösung ist fair? Sabrina bleibt grundsätzlich hinten. In einer ruhigen Phase übt Sabrina vorne und Michael unterstützt sie. Die Aufgaben werden gar nicht mehr verteilt. Genau. Lernen und faire Aufgabenverteilung stärken das Team. Danke. Wenn ich die Chance bekomme, kann ich mich entwickeln und später flexibler helfen. Michael Gestern hast du in unserer Schicht sehr langsam gearbeitet. Was fehlt in dieser Aussage? Eine offene Frage nach dem Grund. Noch mehr Kritik. Eine Drohung. Richtig. Erst nachfragen, bevor man bewertet. Mir ging es gestern nicht gut und ich fühlte mich krank. Heute bin ich wieder fit. Danke für dein Verständnis. Sabrina Michael, könntest du am Samstag meine Spätschicht übernehmen? Michael kann nicht tauschen. Wie antwortet er konstruktiv? Nein. Ende der Diskussion. Leider kann ich nicht, weil ich die Kinder betreue. Lass uns gemeinsam nach einer anderen Lösung suchen. Das ist nicht mein Problem. Richtig. Eine klare Begründung und die gemeinsame Suche nach Alternativen vermeiden Missverständnisse. Das wusste ich nicht. Danke, dass du es erklärst und trotzdem mit mir nach einer Lösung suchst. Marc Konflikte werden selten besser, wenn man sie sammelt und irgendwann explodiert. Laura Teilnehmer, du hast gesehen: Ein gutes Team fragt nach, hört zu und sucht Lösungen, statt Schuldige zu suchen.","tip":"Sprich früh, ruhig und konkret. Beschreibe die Situation, höre die andere Sicht an und vereinbare einen nächsten Schritt."},{"kind":"academy","module":"rechenfehler","part":"Teil 2","section":"Folge 4","chapter":4,"title":"Der Rechenfehler","text":"Im größten Trubel fair, sicher und professionell bleiben. Bestelländerungen sicher erfassen, Unterbrechungen beherrschen und Fehler transparent korrigieren laura marc michael sabrina Laura Teilnehmer, es ist Hochbetrieb. Ein Gast bestellt mehrere Getränke, Essen und gibt Pfandgläser zurück. Dann ändert er seine Bestellung zweimal. Michael Ich versuche alles im Kopf zu behalten. Gleichzeitig fragt ein anderer Gast etwas und unterbricht mich. Was hilft jetzt am meisten? Weiter im Kopf rechnen und hoffen, dass alles stimmt. Die Bestellung Schritt für Schritt im KC Bilderrechner erfassen und Änderungen dort korrigieren. Den Gast bitten, später wiederzukommen. Richtig. Der KC Bilderrechner hält Änderungen, Pfand und Gesamtsumme nachvollziehbar fest. So entsteht Sicherheit für Gast und Mitarbeiter, auch wenn es hektisch wird. Michael Der Gast kommt zurück und sagt verärgert, ich hätte zu viel kassiert und wolle ihn betrügen. Wie reagiert Michael professionell? Sofort widersprechen. Ruhig bleiben, die erfassten Positionen gemeinsam prüfen, sich bei einem Fehler entschuldigen und den Betrag korrigieren. Die Verantwortung an Sabrina abgeben. Genau. Transparenz und eine schnelle Korrektur stellen Vertrauen wieder her. Fehler können passieren. Entscheidend ist, dass offen und fair damit umgegangen wird. Marc Der KC Bilderrechner nimmt uns das Denken nicht ab. Er hilft uns aber, auch bei Änderungen und Unterbrechungen sicher zu arbeiten.","tip":"Erfasse jede Änderung sofort. Verlasse dich im Hochbetrieb nicht auf Kopfrechnen und Gedächtnis."},{"kind":"academy","module":"gas","part":"Teil 2","section":"Folge 5","chapter":5,"title":"Gas alle – und jetzt?","text":"Im Hochbetrieb ruhig bleiben, Aufgaben verteilen und vorbereitet handeln. Krisen ruhig lösen, Verantwortung übernehmen und Vorräte vorbeugend prüfen laura marc michael sabrina dr_brinkmann Sabrina Die Gasflasche ist leer. Gleichzeitig wartet eine Schulklasse auf zwanzig vorbestellte Apfelpunsch. Was ist jetzt der beste erste Schritt? Michael Vorwürfe machen. Ruhe bewahren, Aufgaben verteilen und sofort nach einer sicheren Ersatzlösung suchen. Die Bestellung kommentarlos absagen. Richtig. Erst die Situation lösen, danach die Ursache gemeinsam klären. Klare Aufgaben und Nachbarschaftshilfe können den Betrieb schnell wiederherstellen. Marc Ein Nachbarstand leiht eine passende Ersatzflasche. Danach vereinbaren Michael und Sabrina eine gemeinsame Kontrolle zu Schichtbeginn.","tip":"Gasvorrat, Ersatzflasche und Anschlüsse gehören auf eine kurze Startcheckliste."},{"kind":"academy","module":"fundsache","part":"Teil 2","section":"Folge 6","chapter":6,"title":"Das verschwundene Erbstück","text":"Fundsachen transparent und schichtübergreifend sicher behandeln. Fundsachen sofort am festgelegten Ort ablegen und alle Beteiligten einweisen laura marc frau_schmitt michael leo Frau Schmitt Ich vermisse mein Goldarmband. Es ist ein Erbstück meiner Mutter und ich glaube, ich habe es am Stand verloren. Leo Ich habe das Armband gefunden und aus Unsicherheit in meine Jackentasche gesteckt, damit es niemand mitnimmt. Was ist künftig richtig? Fundsachen in der eigenen Tasche sichern. Sofort am festgelegten Fundsachenplatz ablegen und alle im Stand informieren. Erst am nächsten Tag darüber sprechen. Richtig. Ein fester Ort schafft Transparenz – auch über Schichtwechsel hinweg. Alle Mitglieder und Aushilfen müssen von Anfang an wissen, wo Fundsachen abgelegt werden. Marc Leo hatte eine gute Absicht, aber ein persönlicher Aufbewahrungsort kann Missverständnisse verursachen.","tip":"Weist auch neue Aushilfen direkt am ersten Tag in den Fundsachenplatz ein."},{"kind":"academy","module":"mettwurst","part":"Teil 2","section":"Folge 7","chapter":7,"title":"Mettwurst klein schneiden","text":"Mit einer kleinen Hilfe einen großen Unterschied machen. besondere Bedürfnisse wahrnehmen, praktische Hilfsmittel nutzen und Arbeitsaufwand verringern laura marc herr_becker michael sabrina gisela julia Herr Becker Ich habe eine Hand verbunden. Könnten Sie mir die Mettwurst bitte klein schneiden? Wie reagiert das Team am besten? Die Bitte wegen der Schlange grundsätzlich ablehnen. Kurz Aufgaben tauschen und die Mettwurst hygienisch in mundgerechte Stücke schneiden. Herrn Becker bitten, jemand anderen zu fragen. Richtig. Eine kleine, machbare Hilfe zeigt echte Gastfreundschaft. Vielen Dank. Diese kleine Hilfe bedeutet mir heute sehr viel. Gisela Bei uns am Bratwurststand nutzen wir einen Bratwurstschneider. Vielleicht wäre das für das nächste Mal auch etwas für euch. Dann geht das schnell, sauber und gleichmäßig. Julia Das spart nicht nur Zeit. Die Gäste freuen sich über mundgerechte Stücke, und wir müssen hinterher weniger Messer und Besteckteile spülen. Welchen zusätzlichen Vorteil nennt Julia? Der Bratwurstschneider ersetzt jede persönliche Hilfe. Es werden weniger Messer und Besteckteile benötigt und gespült. Die Mettwurst muss nicht mehr warm gehalten werden. Genau. Ein passendes Hilfsmittel verbessert den Service und reduziert gleichzeitig den Arbeitsaufwand. Kleine organisatorische Verbesserungen helfen Gästen und Team zugleich. Laura Nicht jeder Gast braucht dasselbe. Gute Gastgeber erkennen besondere Situationen und prüfen, ob ein praktisches Hilfsmittel die Lösung dauerhaft erleichtert.","tip":""},{"kind":"academy","module":"probierschluck","part":"Teil 2","section":"Folge 8","chapter":8,"title":"Ein kleiner Probeschluck","text":"Familien freundlich beraten und Spezialitäten erlebbar machen. ehrlich beraten, kleine Probierangebote nutzen und ohne Druck verkaufen laura marc sabrina Sabrina Eine Familie fragt nach Fanta oder Limonade. Das bieten wir nicht an. Ich biete den Kindern einen kleinen Probeschluck Kinder- oder Apfelpunsch an. Warum ist das eine gute Lösung? Die Familie wird zum Kauf gedrängt. Die Kinder können selbst entscheiden und lernen eine passende Alternative kennen. Softgetränke werden dadurch ersetzt. Richtig. Ein Probeschluck nimmt Unsicherheit, ohne Druck auszuüben. Die Kinder finden den Punsch lecker, die Mutter ist zufrieden und die Familie bleibt gern am Stand. Marc Ein kleiner Service kann Gäste überraschen und gleichzeitig Vertrauen in unsere eigenen Produkte zeigen.","tip":""},{"kind":"academy","module":"hund","part":"Teil 2","section":"Folge 9","chapter":9,"title":"Der unerwartete Besucher","text":"Wenn ein Hund an die Reservemettwürste gelangt, zählt professionelles Handeln. kontaminierte Lebensmittel sperren, Bereich reinigen und offen kommunizieren laura marc michael sabrina dr_brinkmann Sabrina Ein großer Hund ist unbemerkt in die Hütte gelangt und hat sich an der Reserveschüssel mit Mettwürsten bedient. Genau jetzt kommt Dr. Brinkmann vorbei. Was muss sofort passieren? Die oberen Würste entfernen und den Rest weiterverwenden. Die gesamte betroffene Ware sperren, Arbeitsbereich sichern und reinigen. Den Vorfall verheimlichen. Richtig. Verunreinigte Lebensmittel werden vollständig aus dem Verkauf genommen. Ein Missgeschick kann passieren. Entscheidend ist, wie konsequent und transparent das Team reagiert. Dr. Brinkmann Ruhiges, ehrliches und fachlich richtiges Handeln schützt die Gäste und erhält Vertrauen.","tip":"Sichert den Zugang zum Lebensmittelbereich so, dass Tiere nicht in die Hütte gelangen können."},{"kind":"academy","module":"allergene","part":"Teil 2","section":"Folge 10","chapter":10,"title":"Allergene","text":"Niemals raten – sicher nachsehen und Auskunft geben. bei Allergenen niemals raten, Informationen sicher prüfen und fachlich korrekt Auskunft geben laura marc frau_schmitt leo dr_brinkmann Frau Schmitt Ich habe eine Laktoseunverträglichkeit. Ist im Heringsstipp Laktose enthalten? Leo kennt die Antwort nicht. Wie reagiert er richtig? Ich bin nur Praktikant, keine Ahnung. Einen Moment bitte. Ich prüfe die Allergeninformationen oder frage einen erfahrenen Kollegen. Das wird schon gut gehen. Richtig. Bei Allergenen wird niemals geraten. Eine verlässliche Auskunft gibt mir Sicherheit und zeigt, dass meine Frage ernst genommen wird. Dr. Brinkmann Auch erfahrene Mitarbeiter kennen nicht jede Rezeptur auswendig. Entscheidend ist, sicher nachzusehen und keine Vermutung als Auskunft weiterzugeben.","tip":"Wenn du unsicher bist: Allergenliste prüfen, Artikelinformation aufrufen oder einen Kollegen fragen."},{"kind":"academy","module":"hygiene","part":"Teil 2","section":"Folge 11","chapter":11,"title":"Hygiene am Stand","text":"Eine anonyme Beschwerde führt zu einer unerwarteten Kontrolle. bei Kontrollen ruhig kooperieren, Hygienerisiken erkennen und Verbesserungen konsequent umsetzen laura marc dr_brinkmann michael sabrina Dr. Brinkmann Guten Abend. Bei der Lebensmittelüberwachung ist eine anonyme Beschwerde über den Stand eingegangen. Ich möchte mir die Arbeitsabläufe ansehen. Wie sollte Michael reagieren? Die Kontrolle sofort zurückweisen. Ruhig begrüßen, kooperieren und die Abläufe offen zeigen. Schnell Dinge verstecken. Richtig. Ruhige Zusammenarbeit schafft Klarheit und Vertrauen. Eine Kontrolle ist kein Angriff. Sie hilft, Risiken zu erkennen und sichere Abläufe zu bestätigen. Dr. Brinkmann Ich finde keine schwerwiegenden Mängel. Zwei Kleinigkeiten sollten Sie verbessern: freie Arbeitswege und eine klarere Trennung sauberer und benutzter Arbeitsmittel.","tip":"Gute Hygiene zeigt sich besonders in klaren Routinen, die auch im größten Andrang funktionieren."},{"kind":"academy","module":"vegetarisch","part":"Teil 2","section":"Folge 12","chapter":12,"title":"Vegetarische Gäste","text":"Ehrlich beraten und auch über den eigenen Stand hinaus helfen. Wünsche ernst nehmen, ehrlich beraten und passende Alternativen empfehlen laura marc michael sabrina Sabrina Ein Gast fragt nach einem vegetarischen Gericht. Kartoffelknirpse mit Dip möchte er nicht. Zwei Stände weiter werden vegetarische Burger angeboten. Welche Reaktion ist gastfreundlich? Den Gast kurz abwimmeln. Ehrlich beraten und freundlich auf die passende Alternative am Nachbarstand hinweisen. Ihm trotzdem Kartoffelknirpse verkaufen. Richtig. Gute Beratung hilft dem Gast auch dann, wenn die beste Lösung nicht am eigenen Stand liegt. Der ehrliche Tipp war hilfreich. Später komme ich gern noch auf einen Punsch zurück. Marc Der Weihnachtsmarkt lebt vom Miteinander. Ein zufriedener Besucher kommt gern wieder.","tip":""},{"kind":"academy","module":"wechselgeld","part":"Teil 2","section":"Folge 13","chapter":13,"title":"Kleingeld und Pfandrückgabe","text":"Ruhig handeln, wenn Wechselgeld oder Pfandgeld knapp wird. Wechselgeld früh prüfen, Gäste offen informieren und im Team eine faire Lösung organisieren laura marc michael sabrina herr_becker Herr Becker Ich möchte drei Pfandgläser zurückgeben. Michael bemerkt, dass gerade kaum Kleingeld in der Kasse liegt. Wie sollte Michael reagieren? Die Rückgabe ablehnen und den Gast wegschicken. Ruhig informieren, den Wechselgeldbestand prüfen und gemeinsam eine sichere Lösung organisieren. So tun, als hätte er den Gast nicht verstanden. Richtig. Offenheit und ein ruhiger Ablauf verhindern Streit. Eine ehrliche Erklärung ist mir lieber als hektisches Improvisieren. Sabrina Sabrina prüft die vereinbarte Wechselgeldreserve und stimmt sich mit Michael ab. So kann das Pfand korrekt zurückgegeben werden.","tip":"Wechselgeld und Pfandreserve gehören auf die Checkliste zum Schichtbeginn und sollten zwischendurch kontrolliert werden."},{"kind":"academy","module":"geldboerse","part":"Teil 2","section":"Folge 14","chapter":14,"title":"Die vergessene Geldbörse","text":"Vertrauen, Regeln und Verantwortung fair abwägen. Gäste respektvoll behandeln, keine Person bloßstellen und eine verantwortbare Lösung finden laura marc frau_schmitt michael sabrina Frau Schmitt Ich habe Sauerkrauteintopf und einen Glühwein bestellt. Jetzt bemerke ich, dass meine Geldbörse noch im Büro liegt. Wie sollte Michael reagieren? Frau Schmitt vor den anderen Gästen bloßstellen. Ruhig bleiben, die Situation respektvoll klären und bei einer Ausnahme gemeinsam eine nachvollziehbare Lösung vereinbaren. Ohne jede Absprache alles verschenken. Richtig. Vertrauen braucht Menschlichkeit und klare Absprachen. Mir war die Situation sehr peinlich. Die ruhige und respektvolle Reaktion hat mir sehr geholfen. Marc Nicht jede Situation lässt sich mit einer starren Antwort lösen. Wichtig sind Transparenz, eine klare Vereinbarung und eine faire Entscheidung.","tip":"Ausnahmen sollten nachvollziehbar bleiben und nicht heimlich oder willkürlich erfolgen."},{"kind":"academy","module":"leo","part":"Teil 2","section":"Folge 15","chapter":15,"title":"Leo kommt ins Team","text":"Neue Helfer willkommen heißen und gut einarbeiten. Voraussetzungen prüfen, neue Helfer persönlich begrüßen, Aufgaben erklären und niemanden allein lassen laura marc leo michael sabrina Leo Ich bin Jungkoch und würde gern einmal zur Probe beim Köcheclub mitarbeiten. Meine gültige Belehrung nach Paragraph 43 Infektionsschutzgesetz habe ich dabei. Was gehört zu einem guten Einstieg? Leo einfach in den Stand stellen und hoffen, dass er alles versteht. Voraussetzungen prüfen, ihn persönlich begrüßen und ihm Ablauf, Hygiene und Aufgaben erklären. Ihn den ganzen Abend nur beobachten lassen. Richtig. Die ersten Minuten entscheiden oft, ob sich ein neuer Helfer willkommen fühlt. Wenn mir jemand alles ruhig zeigt, kann ich sicherer mithelfen und Fragen stellen. Sabrina Michael schaut längere Zeit auf sein Handy. Sabrina merkt, dass Leo unsicher allein steht, und zeigt ihm Händewaschen, Arbeitsbereiche und die ersten Aufgaben. Was ist jetzt besonders wichtig? Leo soll selbst herausfinden, was zu tun ist. Eine feste Ansprechperson kümmert sich um ihn und gibt ihm überschaubare Aufgaben. Leo wird sofort im größten Andrang allein eingesetzt. Genau. Gute Einarbeitung schafft Sicherheit und bindet neue Menschen an das Team. Eigentlich wollte ich nur einmal reinschnuppern. Jetzt merke ich, dass der Köcheclub mehr ist als nur Grünkohl verkaufen. Marc Neue Helfer bringen frische Ideen und neue Energie. Dafür müssen sie von Anfang an ernst genommen und gut eingewiesen werden.","tip":""},{"kind":"academy","module":"kind","part":"Teil 2","section":"Folge 16","chapter":16,"title":"Das verlorene Kind","text":"Ruhig helfen, Verantwortung teilen und Sicherheit geben. ein verlorenes Kind beruhigen, nicht allein lassen und Aufgaben im Team verteilen laura marc michael sabrina Sabrina Ein kleines Mädchen steht weinend am Stand. Es hat seine Mutter verloren. Was ist jetzt besonders wichtig? Das Kind allein zur Marktleitung schicken. Das Kind beruhigen, niemals allein lassen und im Team Unterstützung organisieren. Die Situation ignorieren, weil viel Betrieb ist. Richtig. Sicherheit und Ruhe haben Vorrang. Eine Person bleibt beim Kind, die andere holt Unterstützung. So wird gemeinsam nach der Mutter gesucht. Laura In einer emotionalen Situation helfen klare Aufgaben: eine Person bleibt beim Kind, eine weitere informiert die zuständige Stelle und sucht Unterstützung.","tip":""},{"kind":"academy","module":"nachbarstand","part":"Teil 2","section":"Folge 17","chapter":17,"title":"Der Nachbarstand","text":"Beschwerden und Grenzen respektvoll klären. Rückmeldungen annehmen, Nachbarschaft respektieren und bei wiederholten Gratiswünschen klare Regeln anwenden laura marc michael sabrina herr_koslowski Herr Koslowski Als Betreiber der Nebenhütte erzähle ich Michael, dass Gäste sich gestern am Köcheclub-Stand unfreundlich behandelt fühlten. Wie sollte Michael reagieren? Den Hinweis sofort als Lüge zurückweisen. Für den Hinweis danken, sachlich nachfragen und das Verhalten im Team prüfen. Den Nachbarn vor seinen Gästen kritisieren. Richtig. Auch unangenehme Rückmeldungen können helfen, besser zu werden. Ich wollte keinen Streit. Mir war wichtig, dass ihr von der Rückmeldung erfahrt. Sabrina Der Nachbar kommt bei fast jedem Schichtwechsel vorbei und erwartet ein kostenloses Getränk. Welche Reaktion ist fair? Jeder gibt heimlich weiter kostenlose Getränke aus. Freundlich auf die gemeinsamen Regeln verweisen und besondere Einladungen klar abstimmen. Ihn laut vor allen Gästen beschuldigen. Richtig. Freundlichkeit und klare Grenzen gehören zusammen. Klare Regeln sind für alle besser und vermeiden Missverständnisse. Marc Gute Nachbarschaft lebt von Respekt, ehrlichen Gesprächen und verlässlichen Regeln.","tip":""},{"kind":"academy","module":"anlieferung","part":"Teil 2","section":"Folge 19","chapter":19,"title":"Autos im Weg – aber richtig!","text":"Anliefern, entladen und Rettungswege freihalten. Fahrzeuge nur kurz zum Be- und Entladen nutzen, Parkverbotszonen respektieren und Rettungswege freihalten laura marc eugen michael sabrina Eugen Hömma, wat is dat denn hier? Die Autos vom Köcheclub stehen schon wieder mitten im Weg. Beim Anliefern dürft ihr kurz halten, aber danach müssen die Karren wech. Rettungswege bleiben frei, verstanden? Was ist beim Be- und Entladen richtig? Das Fahrzeug den ganzen Tag vor dem Stand stehen lassen. Kurz be- oder entladen und das Fahrzeug anschließend sofort entfernen. Den Rettungsweg blockieren, solange jemand am Fahrzeug bleibt. Richtig. Kurzes Be- und Entladen ist etwas anderes als dauerhaftes Parken. Wenn die Wege frei bleiben, kommen Lieferanten, Einsatzkräfte und Besucher sicher durch. Marc Klare Absprachen vor Schichtbeginn verhindern, dass Fahrzeuge im falschen Moment oder an der falschen Stelle stehen bleiben.","tip":"Vor der Anlieferung festlegen: Wer fährt, wo wird kurz gehalten und wohin kommt das Fahrzeug danach?"},{"kind":"academy","module":"vorplatz","part":"Teil 2","section":"Folge 20","chapter":20,"title":"Der Vorplatz gehört dazu","text":"Kippen, Scherben und Müll rechtzeitig beseitigen. den Vorplatz regelmäßig kontrollieren, Gefahren sofort beseitigen und Verantwortung gemeinsam übernehmen laura marc eugen gisela michael sabrina Eugen Hömma, soll dat hier so aussehen? Kippen, kaputte Glasflaschen und Servietten direkt vor eurem Stand. Da muss einer ma eben mit dem Besen ran, bevor noch jemand reintritt. Wie sollte das Team reagieren? Bis zum Marktende warten. Gefahren sofort beseitigen und den Vorplatz regelmäßig kontrollieren. Nur den Bereich direkt hinter dem Tresen sauber halten. Richtig. Der Vorplatz gehört zum sicheren und gepflegten Standbetrieb. Sauberkeit beginnt nicht erst hinter dem Tresen. Gisela Bei uns gegenüber schaut jede Stunde jemand kurz vor den Stand. Fünf Minuten reichen oft schon, damit sich gar nicht erst so viel ansammelt.","tip":"Kurze, feste Kontrollrunden sind wirksamer als eine große Aufräumaktion am Ende."},{"kind":"academy","module":"parkgenehmigung","part":"Teil 2","section":"Folge 21","chapter":21,"title":"Parkgenehmigung rechtzeitig klären","text":"Wichtige Fahrzeuge legal und planbar einsetzen. notwendige Fahrzeuge frühzeitig benennen und erforderliche Genehmigungen bei der Stadt beantragen laura marc eugen michael Eugen Wenn ein wichtiges Fahrzeug während des Marktes in der Nähe bleiben muss, reicht kein Zettel hinter der Scheibe. Dafür müsst ihr rechtzeitig eine Genehmigung bei der Stadt beantragen. Wann sollte eine Parkgenehmigung geklärt werden? Erst wenn ein Verwarnzettel am Fahrzeug hängt. Frühzeitig vor dem Weihnachtsmarkt und nur für wirklich notwendige Fahrzeuge. Gar nicht, weil Vereinsfahrzeuge immer frei parken dürfen. Richtig. Genehmigungen werden vorab geklärt und nicht im laufenden Betrieb improvisiert. Planung verhindert Ärger und hält die Marktwege frei. Laura Eine Genehmigung ist kein Freibrief. Auch genehmigte Fahrzeuge müssen so stehen, dass Sicherheit und Rettungswege gewährleistet bleiben.","tip":""},{"kind":"academy","module":"kalleblick","part":"Teil 2","section":"Folge 22","chapter":22,"title":"Kalle sieht, was Gäste sehen","text":"Der Vorplatz prägt den ersten Eindruck. die Perspektive der Gäste einnehmen und kleine Mängel früh erkennen laura marc kalle eugen gisela Kalle Tach auch. Ich komm ja gern zu euch, aber heute musste ich erst um Kippen und Scherben herumsteigen. Dat Essen kann noch so gut sein – der erste Eindruck liegt nun mal vor der Hütte. Warum ist Kalles Hinweis wertvoll? Weil Gäste oft Dinge wahrnehmen, die das Team im Stress übersieht. Weil nur Stammgäste über Sauberkeit entscheiden dürfen. Weil der Vorplatz nichts mit dem Stand zu tun hat. Richtig. Die Sicht der Gäste hilft, blinde Flecken zu erkennen. Ein ehrlicher Hinweis kann helfen, bevor sich weitere Gäste ärgern. Gisela Kalle sagt es zwar mit einem Spruch, aber er hat recht. Wir sollten Hinweise nicht persönlich nehmen, sondern prüfen und handeln.","tip":""},{"kind":"academy","module":"mantaplatte","part":"Teil 2","section":"Folge 23","chapter":23,"title":"Kalle und die Manta-Platte","text":"Warum auch Köchinnen und Köche nach Feierabend manchmal Appetit auf etwas ganz anderes haben. Abwechslung im Teamalltag respektieren, humorvolle Bemerkungen freundlich einordnen und die eigene Arbeit trotzdem wertschätzen laura marc kalle hannes Laura Es ist später Abend auf dem Weihnachtsmarkt. Der große Ansturm ist vorbei. Kalle lehnt gemütlich am Stand, hält seinen täglichen Glühwein in der Hand und beobachtet den Platz. Kalle Na, ihr seid ja Gourmets! Da verkauft ihr den ganzen Tag eure leckeren Gerichte – und abends holt ihr euch Currywurst mit Pommes. Eine richtige Manta-Platte! Ha, ha, ha! Wie lässt sich Kalles Spruch am besten einordnen? Als freundlicher, humorvoller Hinweis – solange niemand abgewertet wird. Als Beweis, dass das Team die eigenen Gerichte nicht mag. Als Grund, den Mitgliedern fremdes Essen zu verbieten. Richtig. Humor darf verbinden. Entscheidend ist, dass er respektvoll bleibt und niemanden bloßstellt. Kalle neckt das Team, ohne die Arbeit oder das Essen des Köcheclubs schlechtzumachen. Hannes Da hast du uns erwischt, Kalle. Natürlich essen wir unsere eigenen Gerichte gerne. Aber wenn man sie den ganzen Tag zubereitet und verkauft, freut man sich abends auch mal auf etwas anderes. Abwechslung muss schließlich sein. Welche Aussage trifft den Kern der Situation? Wer auswärts isst, steht nicht hinter der eigenen Küche. Abwechslung nach einer langen Schicht ist normal und mindert die Wertschätzung der eigenen Gerichte nicht. Clubmitglieder sollten nur essen, was am eigenen Stand angeboten wird. Genau. Appetit auf Abwechslung und Stolz auf die eigene Arbeit passen gut zusammen. Kalle Du hast ja recht, Hannes. Ich esse schließlich auch nicht jeden Abend Bratkartoffeln mit Spiegelei. Manchmal gibt es auch eine Frikadelle mit ordentlich Senf dazu! Marc Alle müssen lachen. Die Currywurst ist an diesem Abend kein Verrat an der eigenen Küche, sondern eine willkommene Abwechslung nach einem langen Arbeitstag.","tip":"Gemeinsames Lachen stärkt ein Team, wenn der Humor freundlich bleibt und die Leistung anderer respektiert."},{"kind":"academy","module":"rueckstellprobe","part":"Teil 2","section":"Folge 24","chapter":24,"title":"Die fehlende Rückstellprobe","text":"Dr. Brinkmann prüft die Dokumentation – und aus einem Versäumnis wird eine verlässliche Routine. Rückstellproben vollständig entnehmen, eindeutig beschriften, sicher einfrieren und den Tagesabschluss mit einer Checkliste organisieren laura marc dr_brinkmann michael Laura Teilnehmer, heute geht es um eine kleine Probe mit großer Bedeutung. Dr. Brinkmann kommt unangekündigt zur Kontrolle an den Stand und bittet um die Rückstellprobe vom Vorabend. Dr. Brinkmann Guten Tag. Zeigen Sie mir bitte die Rückstellprobe des Grünkohls vom gestrigen Abend sowie den zugehörigen Eintrag im Rückstellprobenbuch. Was sollte Michael jetzt als Erstes tun? Offen und wahrheitsgemäß erklären, was dokumentiert wurde und was fehlt. Schnell eine neue Probe abfüllen und mit dem gestrigen Datum versehen. Behaupten, die Probe sei bereits entsorgt worden. Richtig. Bei einer Kontrolle zählen Ehrlichkeit, nachvollziehbare Unterlagen und die sofortige Klärung des Versäumnisses. Michael Herr Dr. Brinkmann, gestern war sehr viel Betrieb. Ich muss offen sagen: Die Probe vom Abend wurde nicht entnommen. Die übrigen Einträge sind vollständig. Dr. Brinkmann Danke für die ehrliche Antwort. Rückstellproben helfen, bei einer späteren Beschwerde die ausgegebene Speise untersuchen zu können. Deshalb müssen Entnahme, Beschriftung, Lagerung und Dokumentation als feste Routine zusammengehören. Welche Dokumentation ist vollständig? Nur das Datum auf dem Behälter. Datum, Uhrzeit und Gericht auf dem Behälter sowie ein nachvollziehbarer Eintrag mit Unterschrift im Rückstellprobenbuch. Ein mündlicher Hinweis an die nächste Schicht. Genau. Behälter und Rückstellprobenbuch müssen die Probe eindeutig und nachvollziehbar zuordnen. Marc Im hektischen Tagesgeschäft darf der Abschluss nicht vom Gedächtnis einer einzelnen Person abhängen. Eine kurze Checkliste macht sichtbar, was erledigt ist und wer die Verantwortung übernommen hat. Michael Ich richte ab heute einen festen Tagesabschluss ein. Erst wenn alle Punkte geprüft und bestätigt sind, ist die Schicht wirklich beendet. Dr. Brinkmann Sehr gut. Entscheidend ist nicht, einen Fehler zu verbergen, sondern seine Ursache zu verstehen und den Ablauf so zu verbessern, dass er nicht erneut passiert. Welche Maßnahme verhindert das Versäumnis am zuverlässigsten? Eine verbindliche Tagesabschluss-Checkliste mit klarer Zuständigkeit und Bestätigung. Eine Erinnerung nur dann, wenn wenig Betrieb ist. Die Aufgabe ohne Dokumentation an wechselnde Personen weitergeben. Richtig. Eine feste Zuständigkeit und eine bestätigte Checkliste machen den Abschluss verlässlich und nachvollziehbar. Laura Teilnehmer, du hast alle Punkte bestätigt. Der Tagesabschluss ist vollständig dokumentiert. So wird aus Aufmerksamkeit eine sichere Routine.","tip":"Die konkreten Vorgaben zu Menge, Aufbewahrungsdauer und Temperatur müssen immer nach dem für den Betrieb geltenden Hygienekonzept und den behördlichen Anforderungen festgelegt werden."},{"kind":"academy","module":"gemeinsam","part":"Teil 2","section":"Folge 25","chapter":25,"title":"Gemeinsam läuft’s rund","text":"Kleine Aufgaben verteilen und als Marktgemeinschaft handeln. Aufgaben teilen, Nachbarstände einbeziehen und gemeinsam für Ordnung und Sicherheit sorgen laura marc eugen gisela kalle michael sabrina Eugen Hömma, einer stellt die Fahrzeuge weg, einer fegt den Vorplatz und einer schaut nach den Lieferwegen. Dann is dat in zehn Minuten erledigt, statt dass alle nur schimpfen. Was ist die beste Lösung? Eine Person macht immer alles allein. Aufgaben klar verteilen und sich gegenseitig unterstützen. Warten, bis die Stadt alles erledigt. Richtig. Kleine, klar verteilte Aufgaben machen den Ablauf zuverlässig. Gisela Ich bringe euch zwei Müllsäcke rüber. Dafür sagt ihr uns Bescheid, wenn bei uns vor dem Stand etwas gefährlich wird. So hilft man sich auf dem Markt. Kalle Und ich pass auf, dass ihr nich wieder die halbe Straße zuparkt. Keine Sorge – ich sag dat schon laut genug. Welche Haltung steckt hinter der Episode? Jeder Stand kümmert sich nur um sich selbst. Gute Zusammenarbeit verbindet klare Verantwortung mit gegenseitiger Hilfe. Gäste sollen organisatorische Aufgaben übernehmen. Richtig. Verlässlichkeit und Nachbarschaftshilfe gehören zusammen. Wenn alle mitdenken, bleibt der Weihnachtsmarkt sicher und freundlich. Marc Organisation wirkt dann professionell, wenn Verantwortung klar ist und trotzdem jeder bereit bleibt, kurz mit anzupacken.","tip":"Am Schichtbeginn zwei Minuten für Zuständigkeiten einplanen: Fahrzeuge, Vorplatz, Müll und Lieferwege."},{"kind":"academy","module":"koslowski_geruch","part":"Teil 2","section":"Folge 26","chapter":26,"title":"Wenn die Ware nach Grünkohl riecht","text":"Eine Beschwerde des Nachbarstands sachlich aufnehmen und gemeinsam lösen. Nachbarschaftskonflikte früh ansprechen, Auswirkungen des eigenen Standbetriebs ernst nehmen und praktikable Lösungen vereinbaren laura marc herr_koslowski michael sabrina Herr Koslowski Hömma Michael, ich muss euch ma watt sagen. Meine Mützen und Schals riechen inzwischen nach Grünkohl und Glühwein. Die Kundschaft merkt dat auch schon. Wie sollte Michael zuerst reagieren? Die Beschwerde abweisen, weil Gerüche auf einem Weihnachtsmarkt normal sind. Für den Hinweis danken, ruhig nachfragen und die Ursache gemeinsam prüfen. Herrn Koslowski sagen, er solle seinen Stand weiter wegstellen. Richtig. Wer den Hinweis ernst nimmt, verhindert, dass aus einem Problem ein dauerhafter Nachbarschaftskonflikt wird. Mir geht es nicht ums Meckern. Ich möchte nur, dass wir eine vernünftige Lösung finden. Sabrina Sabrina schlägt vor, die Topfdeckel konsequenter geschlossen zu halten, die Dampfentwicklung zu beobachten und die Lüftungsrichtung gemeinsam zu prüfen. Welche Lösung ist besonders sinnvoll? Nichts verändern und hoffen, dass sich Herr Koslowski daran gewöhnt. Konkrete Maßnahmen testen und mit dem Nachbarstand vereinbaren, ob sie wirken. Nur während einer Kontrolle die Deckel schließen. Genau. Gute Zusammenarbeit bedeutet, Maßnahmen zu vereinbaren und anschließend gemeinsam zu prüfen, ob sie helfen. Wenn wir merken, dass es besser wird, ist für beide Stände viel gewonnen. Marc Beschwerden von Nachbarständen sind keine persönlichen Angriffe. Sie zeigen, wo der eigene Betrieb andere beeinflusst.","tip":"Früh sprechen, konkret prüfen, Lösung vereinbaren und später kurz nachfragen, ob die Verbesserung ausreicht."},{"kind":"academy","module":"kinderbetreuung","part":"Teil 2","section":"Folge 27","chapter":27,"title":"Wenn die Kinderbetreuung ausfällt","text":"Verantwortung und Hilfsbereitschaft miteinander verbinden. Gefahren am Stand realistisch einschätzen, Grenzen freundlich erklären und gemeinsam eine sichere Lösung suchen laura marc julia michael Julia Mein Kindermädchen für den zehnjährigen Alexander ist kurzfristig ausgefallen. Könnte er heute in der Nebenhütte auf dem Boden spielen, während ich ein paar Stunden am Stand helfe? Michael Ich verstehe deine Lage, aber am Stand und in der Nebenhütte gibt es heiße Flüssigkeiten, Gas, Messer, Lieferverkehr und keine durchgehende Aufsicht. Das wäre zu gefährlich. Wie sollte Michael jetzt weiter reagieren? Julia ohne weitere Hilfe nach Hause schicken. Die Gefahr klar benennen und anschließend gemeinsam nach einer sicheren Betreuungsmöglichkeit suchen. Alexander unbeaufsichtigt in der Nebenhütte spielen lassen. Richtig. Sicherheit hat Vorrang, aber eine Absage sollte möglichst mit einem lösungsorientierten Vorschlag verbunden werden. Julia fühlt sich ernst genommen, obwohl ihr ursprünglicher Wunsch nicht möglich ist. Michael Meine Frau hat heute frei. Ich rufe sie an und frage, ob Alexander während deiner Schicht bei ihr bleiben kann. Dann kannst du helfen und er ist zuverlässig betreut. Laura Verantwortung bedeutet, ein Risiko klar abzulehnen und trotzdem respektvoll nach einer machbaren Alternative zu suchen.","tip":"Private Hilfe ist freiwillig und muss für alle Beteiligten passen. Entscheidend ist, dass Kinder nicht unbeaufsichtigt in einem Arbeits- oder Gefahrenbereich bleiben."},{"kind":"academy","module":"wasserschlauch","part":"Teil 2","section":"Folge 28","chapter":28,"title":"Der geplatzte Wasserschlauch","text":"In einer Notsituation ruhig handeln und wichtige Einrichtungen kennen. Aushilfen vollständig einweisen, Wasser schnell abstellen, Notfallkontakte finden und Gefahrenbereiche sichern julia kalle michael marc Julia Michael ist kurz zur Toilette gegangen. Plötzlich platzt an der Spülmaschine ein Wasserschlauch. Wasser läuft über den Boden und ich weiß im ersten Moment nicht, was ich tun soll. Was ist jetzt als Erstes wichtig? Den Stand verlassen und niemandem etwas sagen. Ruhe bewahren, andere warnen und versuchen, die Wasserzufuhr sicher zu stoppen. Weiterarbeiten, bis Michael zurückkommt. Richtig. Personen warnen, Rutsch- und Stromgefahren beachten und die Wasserzufuhr so schnell wie möglich sicher stoppen. Eine klare Einweisung hilft, auch unter Stress handlungsfähig zu bleiben. Kalle Julia, hinter der Ausgangstür hängen doch die wichtigen Telefonnummern. Da stehen Feuerwehr, Polizei, Gas, Wasserinstallateur und Elektriker. Michael Ich bin zurück und zeige Julia sofort den Absperrhahn. Wir stellen das Wasser ab, sichern den nassen Bereich und prüfen, ob elektrische Geräte gefährdet sind. Was muss jede neue Aushilfe vor ihrer ersten Schicht kennen? Nur die Speisekarte. Erste-Hilfe-Kasten, Feuerlöscher, Gas-, Wasser- und Stromabschaltung, Fluchtwege und Notfallnummern. Nur den eigenen Arbeitsplatz. Genau. Eine vollständige Einweisung ist ein wichtiger Teil der Arbeitssicherheit. Julia weiß jetzt, wo sie im Notfall handeln und Hilfe holen kann. Marc Neue Kolleginnen, Kollegen, Aushilfen und Praktikanten müssen vor der ersten Schicht eine kurze Notfalleinweisung erhalten.","tip":"Notfallnummern müssen gut sichtbar, aktuell und für alle Helfer erreichbar sein. ()=>resolveSystemText('emergency_checklist')"},{"kind":"academy","module":"freundliches_wort","part":"Teil 2","section":"Folge 30","chapter":30,"title":"Ein freundliches Wort","text":"Hannes zeigt Leo, wie Gastfreundschaft schon mit der Begrüßung beginnt. Gäste freundlich begrüßen, Blickkontakt halten, Ruhe ausstrahlen und Fehler nicht mit Unfreundlichkeit verwechseln hannes leo laura Leo Ich bin heute etwas nervös. Ich möchte bloß nichts falsch machen. Hannes Weißt du, woran sich unsere Gäste später erinnern? Nicht daran, ob du zuerst die linke oder die rechte Taste gedrückt hast. Sondern daran, ob sie freundlich empfangen wurden. Was ist beim ersten Kontakt besonders wichtig? Möglichst schnell sprechen. Freundlich begrüßen, Blickkontakt halten und Ruhe ausstrahlen. Jeden Gast sofort auf mögliche Fehler hinweisen. Richtig. Ein freundlicher erster Kontakt schafft Vertrauen. Ein ehrliches Lächeln und ein ruhiger Gruß nehmen vielen Gästen sofort die Unsicherheit. Laura Leo begrüßt ein älteres Ehepaar freundlich: Schön, dass Sie da sind. Was darf ich Ihnen anbieten? Beide lächeln sofort zurück. Hannes Siehst du? Genau so entsteht Gastfreundschaft. Und jetzt gönne ich mir erst einmal einen Kaffee. Ohne Kaffee bin ich morgens nur halb so freundlich.","tip":"Ein freundliches Wort kostet nichts und bleibt Gästen oft länger im Gedächtnis als ein kleiner Bedienfehler."},{"kind":"academy","module":"zwei_euro","part":"Teil 2","section":"Folge 31","chapter":31,"title":"Die zwei Euro","text":"Detlef zeigt, warum ein ruhiger Kassenabschluss wichtig ist. sorgfältig zählen, Abweichungen ruhig prüfen, niemanden vorschnell beschuldigen und gemeinsam nach der Ursache suchen detlef leo marc laura Leo Detlef, du zählst aber wirklich jeden Cent. Detlef Bei Geld lohnt sich Genauigkeit. Moment ... zwei Euro fehlen. Wie sollte das Team jetzt reagieren? Sofort jemanden verantwortlich machen. In Ruhe noch einmal zählen und gemeinsam nach einer einfachen Erklärung suchen. Die Abweichung ignorieren, weil es nur zwei Euro sind. Genau. Erst prüfen, dann bewerten. Ruhe und ein klarer Ablauf verhindern unnötige Verdächtigungen. Laura Unter dem Pfandglas liegt eine Zwei-Euro-Münze. Alle müssen schmunzeln. Detlef Da ist sie ja. Die wollte wohl noch bis zum Schluss dabei bleiben. Genau deshalb kontrollieren wir sorgfältig und ohne Hektik.","tip":"Bei einer Abweichung zuerst Bestände, Ablageflächen, Pfandgefäße und Wechselgeld gemeinsam prüfen."},{"kind":"academy","module":"bereitschaft","part":"Teil 2","section":"Folge 32","chapter":32,"title":"Gut geplant ist halb gewonnen","text":"Laura organisiert bei einem kurzfristigen Ausfall den Bereitschaftsdienst. Dienstplan, Bereitschaft und aktuelle Telefonnummern nutzen, Ausfälle ruhig auffangen und Informationen zuverlässig weitergeben laura michael hannes Laura Kurz vor dem Spätdienst schreibt Michael in die Clubgruppe, dass er sich krank fühlt und heute nicht kommen kann. Für den Abend wird großer Andrang erwartet. Was ist jetzt die beste erste Reaktion? Michael Vorwürfe machen. Den Dienstplan prüfen und den eingetragenen Bereitschaftsdienst anrufen. Den Stand ohne Ersatz öffnen. Richtig. Gute Planung schafft eine klare Reserve für kurzfristige Ausfälle. Der Bereitschaftskollege ist erreichbar und kann rechtzeitig einspringen. Laura An der Pinnwand finde ich den aktuellen Dienstplan mit Bereitschaft und Telefonnummer. Der Kollege sagt sofort zu und ist in zwanzig Minuten da. Hannes Danke für die Information. Genau dafür planen wir unsere Bereitschaften. Gut, dass alles geregelt ist. Was gehört zu einem verlässlichen Bereitschaftssystem? Nur ein Name ohne Telefonnummer. Aktueller Dienstplan, erreichbare Telefonnummern und klare Information bei Änderungen. Eine spontane Suche erst nach Dienstbeginn. Genau. Nur aktuelle und zugängliche Informationen helfen im Ernstfall. Die Gäste merken von dem kurzfristigen Ausfall nichts. Marc Eine gute Planung inklusive Reserve ist eine Voraussetzung für einen funktionierenden Dienst und einen verlässlichen Weihnachtsmarkt.","tip":"Prüft regelmäßig, ob Bereitschaftsdienste und Telefonnummern noch aktuell sind."},{"kind":"academy","module":"barzahlung","part":"Teil 2","section":"Folge 33","chapter":33,"title":"Bitte nur Barzahlung","text":"Ein klarer Hinweis vermeidet unangenehme Situationen beim Bezahlen. Zahlungsmöglichkeiten früh und sichtbar kommunizieren und in einer unangenehmen Situation freundlich bleiben michael kalle herr_becker marc laura Herr Becker Ich möchte vier Portionen Grünkohl mit Mettwurst zum Mitnehmen und halte Michael meine Kreditkarte hin. Michael Es tut mir leid. Beim Köcheclub ist ausschließlich Barzahlung möglich. Wie lässt sich diese Situation künftig vermeiden? Erst beim Bezahlen darauf hinweisen. Vor der Bestellung gut sichtbar auf Nur Barzahlung hinweisen. Nur Stammgäste informieren. Richtig. Klare Informationen verhindern Missverständnisse. Der Gast hat kein Bargeld dabei und die Situation ist ihm unangenehm. Kalle Ich kenne Herrn Becker und übernehme die Rechnung. Beim nächsten Treffen gleichen wir das wieder aus. Marc Der hilfreiche Zufall löst die Situation. Besser ist aber ein gut sichtbarer Aushang: Bitte beachten – bei uns ist nur Barzahlung möglich.","tip":"Der Hinweis gehört dorthin, wo Gäste sich anstellen oder bestellen, nicht erst an die Kasse."},{"kind":"academy","module":"panne","part":"Teil 2","section":"Folge 34","chapter":34,"title":"Gemeinsam finden wir eine Lösung","text":"Eine Autopanne kurz vor dem Schichtwechsel fordert Flexibilität und Teamgeist. bei kurzfristiger Verspätung sofort informieren, vorhandene Teamressourcen respektvoll ansprechen und eine zeitlich begrenzte Übergangslösung vereinbaren michael sabrina hannes laura marc Sabrina Es ist 14 Uhr 55. Michael muss heute pünktlich gehen, weil er einen wichtigen Arzttermin hat. Marius, der um 15 Uhr übernehmen sollte, ruft an: Sein Wagen hat eine Panne und er schafft es nicht rechtzeitig. Was ist jetzt der wichtigste erste Schritt? Michael sagt seinen Arzttermin ab. Die Situation ruhig klären und prüfen, wer am Stand vorübergehend länger bleiben kann. Den Stand sofort schließen. Richtig. Zuerst wird ruhig geprüft, welche sichere und faire Übergangslösung im vorhandenen Team möglich ist. Marius hat frühzeitig angerufen. Dadurch bleibt noch Zeit, gemeinsam zu reagieren. Michael Ein weiterer Kollege arbeitet bereits mit uns am Stand und hätte ebenfalls um 15 Uhr Feierabend. Ich frage ihn: Ich weiß, dein Dienst wäre jetzt eigentlich zu Ende. Wäre es für dich möglich, heute ausnahmsweise bis 17 Uhr zu bleiben? Dann übernimmt der Bereitschaftsdienst. Wie sollte eine solche Bitte gestellt werden? Als selbstverständliche Anweisung ohne Nachfrage. Respektvoll, freiwillig und mit einer klaren zeitlichen Begrenzung. Erst nach dem eigentlichen Feierabend. Genau. Zusätzliche Hilfe wird wertschätzend erfragt, nicht vorausgesetzt. Der Kollege überlegt kurz und erklärt sich bereit, bis 17 Uhr länger zu bleiben. Sabrina Damit ist der Stand weiter gut besetzt. Michael kann seinen Arzttermin wahrnehmen, und ab 17 Uhr übernimmt wie geplant der Bereitschaftsdienst. Hannes Ein guter Dienstplan gibt Orientierung. Ein gutes Team findet auch dann eine faire Lösung, wenn etwas Unvorhergesehenes passiert. Warum konnte die Situation gut gelöst werden? Weil Michael seinen Termin abgesagt hat. Weil offen kommuniziert, freiwillige Hilfe erfragt und die Übergabe klar begrenzt wurde. Weil Marius trotz der Panne rechtzeitig kam. Richtig. Offene Kommunikation und freiwillige Unterstützung schaffen eine verlässliche Übergangslösung. Niemand wird beschuldigt oder unter Druck gesetzt. Die Aufgabe wird gemeinsam und zeitlich klar geregelt. Laura Wer merkt, dass er sich verspätet oder ausfällt, sollte das Team sofort informieren. So bleibt genügend Zeit, gemeinsam eine gute Lösung zu finden.","tip":"Zusätzliche Arbeitszeit immer freiwillig, respektvoll und mit klarer Dauer vereinbaren. Danach die Änderung an die zuständigen Personen weitergeben."},{"kind":"academy","module":"verbandskasten","part":"Teil 2","section":"Folge 35","chapter":35,"title":"Frau Schmitt, das Pflaster und der neue Verbandskasten","text":"Ein Schnitt durch eine Glasscherbe zeigt, warum Erste Hilfe vorbereitet sein muss. bei Verletzungen Eigenschutz beachten, Erste Hilfe leisten, den Verbandskasten schnell finden und bei ernsten Verletzungen unverzüglich den Rettungsdienst alarmieren frau_schmitt herr_becker sabrina michael detlef marc Frau Schmitt An einem gut besuchten Abend bestelle ich einen Eierlikörpunsch ohne Sahne, weil ich eine Laktoseintoleranz habe. Sabrina bestätigt freundlich, dass das möglich ist. Kurz darauf stößt mich ein anderer Gast versehentlich an. Das Glas fällt zu Boden und zerbricht. Was ist nach dem Zerbrechen des Glases zuerst wichtig? Die Scherben sofort mit bloßen Händen aufheben. Den Bereich sichern, Gäste warnen und geeignete Hilfsmittel zum Aufnehmen der Scherben verwenden. Die Scherben bis zum Ende des Abends liegen lassen. Richtig. Zuerst wird der Gefahrenbereich gesichert. Glasscherben werden niemals mit bloßen Händen aufgenommen. Eine klare Warnung schützt Gäste und Team vor weiteren Verletzungen. Herr Becker Ich möchte helfen und beginne, die Scherben mit bloßen Händen aufzuheben. Dabei schneidet eine scharfe Scherbe tief in meinen Daumen. Die Wunde beginnt stark zu bluten. Wie sollte das Team jetzt reagieren? Eigenschutz beachten, Hilfe holen, die Blutung mit geeignetem Verbandmaterial versorgen und die Schwere der Verletzung beurteilen. Nur ein beliebiges Pflaster aufkleben und sofort weiterarbeiten. Die Wunde ignorieren, solange Herr Becker stehen kann. Genau. Ersthelfende schützen sich selbst, versorgen die Blutung fachgerecht und holen bei Bedarf unverzüglich professionelle Hilfe. Sabrina Ich suche in mehreren Schubladen nach Pflastern. Michael erinnert sich, dass sie im vergangenen Jahr zwischen den Handtüchern lagen. Dort sind sie aber nicht mehr. Erst in einer anderen Schublade finden wir noch geeignetes Verbandmaterial. Welches organisatorische Problem wird hier sichtbar? Verbandmaterial wird nur selten benötigt und braucht deshalb keinen festen Platz. Der Aufbewahrungsort ist nicht eindeutig, nicht allen bekannt und offenbar nicht regelmäßig kontrolliert worden. Nur die Standverantwortung darf wissen, wo Erste-Hilfe-Material liegt. Richtig. Notfallausrüstung braucht einen festen, gekennzeichneten und allen bekannten Platz. Detlef Am Ende des Abends notiere ich die Anschaffung eines vollständigen Verbandskastens. Schon wenige Tage später hängt er gut sichtbar und schnell erreichbar im Stand. Was gehört zusätzlich zur Anschaffung? Regelmäßige Kontrolle von Inhalt, Vollständigkeit und Verwendbarkeit sowie eine Einweisung des Teams. Der Kasten bleibt verschlossen und nur eine Person erhält den Schlüssel. Eine Kontrolle ist erst nach einem Unfall notwendig. Richtig. Ein Verbandskasten hilft nur, wenn er erreichbar, vollständig, verwendbar und allen bekannt ist. Marc Ein Erste-Hilfe-Kasten gehört aus Sicherheitsgründen in jeden Stand. Er muss schnell erreichbar sein und jeder muss wissen, wo er hängt. Bei starker Blutung, einer tiefen Wunde, Kreislaufproblemen oder anderen ernsten Verletzungen gilt: Sofort professionelle Hilfe über den Notruf 112 alarmieren und keine Zeit verlieren.","tip":"Notfallausrüstung zu Schichtbeginn kurz prüfen: Standort frei zugänglich, Kennzeichnung sichtbar, Inhalt vollständig und Verfallsdaten kontrolliert."},{"kind":"academy","module":"papiertuete","part":"Teil 2","section":"Folge 36","chapter":36,"title":"Die brennende Papiertüte","text":"Ein kleiner Entstehungsbrand zeigt, wie wichtig Einweisung, Abstand und der Notruf 112 sind. Brand früh melden, Menschen warnen, Fluchtwege freihalten, einen Entstehungsbrand nur ohne Selbstgefährdung bekämpfen und bei wachsender Gefahr sofort 112 wählen gisela herr_koslowski kalle michael marc Gisela Es ist ein lebhafter Abend. Hinter der Nachbarbude entdecke ich eine kleine Flamme. Offenbar hat eine noch glimmende Zigarettenkippe eine trockene Papiertüte entzündet. Ich rufe sofort laut: Feuer! Was bewirkt Giselas lauter Warnruf? Andere werden früh gewarnt und können Abstand halten beziehungsweise Hilfe organisieren. Der Brand wird dadurch automatisch gelöscht. Nur die Gäste werden unruhig, deshalb sollte man schweigen. Richtig. Frühes Warnen schützt Menschen und setzt die notwendige Hilfe in Gang. Henn Koslowski Ich achte darauf, dass niemand zu nah an die Flammen kommt und der Weg für Helfende frei bleibt. Kalle ruft Michael hinzu. Warum ist das Absichern des Bereichs wichtig? Damit niemand durch Feuer, Rauch oder hektische Bewegungen zusätzlich gefährdet wird. Damit möglichst viele Menschen beim Löschen zusehen können. Damit der Standbetrieb unverändert weiterlaufen kann. Genau. Menschenrettung und Eigenschutz haben Vorrang vor Sachwerten. Michael Ich weiß, wo der Feuerlöscher hängt, hole ihn und prüfe auf dem Weg, ob ich den kleinen Brand gefahrlos bekämpfen kann. Ich beachte die Bedienhinweise des Löschers, halte einen sicheren Rückweg frei und lösche den Entstehungsbrand mit kurzen, gezielten Stößen. Wann ist ein eigener Löschversuch vertretbar? Nur bei einem kleinen Entstehungsbrand, wenn der Löscher geeignet ist, ein sicherer Rückweg besteht und keine Selbstgefährdung entsteht. Bei jedem Brand, unabhängig von Rauch und Ausbreitung. Nur wenn vorher alle Gäste zugestimmt haben. Richtig. Ein Löschversuch darf niemals die eigene Sicherheit gefährden. Marc Zum Glück ist das Feuer nach wenigen Sekunden aus. Jeder im Team muss wissen, wo der Feuerlöscher hängt und wie die grundlegende Alarmierung funktioniert. Wird ein Feuer größer, entsteht starker Rauch oder sind Menschen gefährdet, gilt immer: Bereich verlassen, andere warnen, Feuerwehr über 112 alarmieren und sich selbst nicht in Gefahr bringen. Was ist bei wachsendem Feuer oder Gefahr für Menschen richtig? Weiterlöschen, bis der Feuerlöscher vollständig leer ist. Sofort warnen, sicheren Bereich aufsuchen, 112 alarmieren und den Anweisungen der Einsatzkräfte folgen. Zuerst Fotos für die Dokumentation machen. Richtig. Alarmierung, Evakuierung und Eigenschutz haben Vorrang. Kalle Na, dann hoffen wir mal, dass unser Feuerlöscher jetzt möglichst lange Pause hat. Am schönsten ist es schließlich, wenn er nur zur Sicherheit an der Wand hängt und nie gebraucht wird.","tip":"Feuerlöscher, Fluchtwege und Notrufhinweise müssen sichtbar und frei zugänglich bleiben. Benutzte oder beschädigte Löscher unverzüglich fachgerecht prüfen beziehungsweise ersetzen lassen."},{"kind":"academy","module":"finale","part":"Teil 2","section":"Folge 37","chapter":37,"title":"Ein Weihnachtsmarkt verbindet","text":"Herr Becker und Frau Schmitt entdecken gemeinsame Interessen. erkennen, wie Gastfreundschaft, Atmosphäre und menschliche Begegnungen den Weihnachtsmarkt prägen laura marc herr_becker frau_schmitt michael sabrina Herr Becker Am letzten Abend stehe ich bei leichtem Schneefall mit einer Feuerzangenbowle am Stehtisch. Frau Schmitt fragt, ob neben mir noch Platz ist. Frau Schmitt Wir kommen ins Gespräch und entdecken viele gemeinsame Interessen. Zwischen Weihnachtslichtern und Wunderkerzen verabreden wir uns zu einem weiteren Treffen. Welche Botschaft steckt in dieser Geschichte? Am Stand zählt nur der schnelle Verkauf. Gastfreundschaft schafft Begegnungen und kann Menschen miteinander verbinden. Gäste sollten möglichst nicht miteinander sprechen. Richtig. Ein menschlicher Weihnachtsmarkt lebt von echten Begegnungen. Manchmal beginnt etwas Schönes mit einem freundlichen Gespräch am Stehtisch. Sabrina Sabrina sagt leise zu Michael: Der Köcheclub bewirtet nicht nur Gäste. Manchmal bringt er auch Menschen zusammen. Marc Rezepte kann man lernen. Eine Kasse kann man bedienen. Aber Herzlichkeit kommt von den Menschen.","tip":"Jedes Jahr machen wir den Weihnachtsmarkt ein bisschen besser – und menschlicher."},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Laura","text":"Trainerin Herzlich willkommen. Ich bin Laura und begleite dich Schritt für Schritt durch die KC FUTURA Academy. Mir ist wichtig, dass du dich sicher fühlst und aus jeder Situation etwas Praktisches mitnimmst. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Marc","text":"Praxiscoach Hallo. Ich bin Marc und begleite dich als Praxiscoach. Mir sind klare Abläufe, gute Zusammenarbeit und Lösungen wichtig, die sich am Weihnachtsmarkt wirklich bewähren. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Herr Becker","text":"langjähriger Stammgast Guten Tag. Ich bin Herr Becker und komme seit vielen Jahren zum Köcheclub. Mir sind ein heißes Getränk, gutes Essen und ein freundliches Wort besonders wichtig. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Frau Schmitt","text":"Stammgast Guten Tag. Ich bin Frau Schmitt. Ich habe eine Laktoseunverträglichkeit und achte deshalb besonders auf verlässliche Allergeninformationen. Außerdem lege ich großen Wert auf Freundlichkeit, Sauberkeit, Qualität und eine ehrliche Beratung. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Lukas","text":"junger Student Hallo. Ich bin Lukas und studiere zurzeit. Mir ist wichtig, freundlich behandelt zu werden und dass der Jugendschutz verantwortungsvoll umgesetzt wird. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Michael","text":"erfahrener Koch Hallo. Ich bin Michael, ein erfahrener Koch. Mir sind Qualität, verlässliche Abläufe und ein gutes Zusammenspiel im Team besonders wichtig. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Sabrina","text":"jüngere Köchin Hallo. Ich bin Sabrina. Mir ist wichtig, dass neue Helfer willkommen sind, Aufgaben fair verteilt werden und wir auch in stressigen Situationen zusammenhalten. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Leo","text":"schüchterner Jungkoch Hallo. Ich bin Leo, Jungkoch und noch etwas zurückhaltend. Ich möchte den Köcheclub kennenlernen, neue Erfahrungen sammeln und Schritt für Schritt meinen Platz im Team finden. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Dr. Brinkmann","text":"Lebensmittelüberwachung Guten Tag. Ich bin Dr. Brinkmann von der Lebensmittelüberwachung. Mir sind sauberes Arbeiten, sichere Lebensmittel und verständliche, praxistaugliche Hygieneregeln besonders wichtig. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Julia","text":"ehrenamtliche Helferin Hallo. Ich bin Julia und unterstütze den Köcheclub zum ersten Mal. Mir ist wichtig, Fragen stellen zu dürfen, gute Erklärungen zu bekommen und Schritt für Schritt sicherer im Team zu werden. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Herr Koslowski","text":"Standnachbar Guten Tag. Ich bin Herr Koslowski vom Nachbarstand und verkaufe Mützen, Schals und Handschuhe. Mir sind gute Nachbarschaft, klare Absprachen und gegenseitige Hilfe auf dem Weihnachtsmarkt besonders wichtig. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Eugen","text":"Hausmeister & Platzwart Hömma, ich bin Eugen, Hausmeister und Platzwart auf dem Weihnachtsmarkt. Mir ist wichtig, dass Anlieferung, Parken, Rettungswege und Sauberkeit vernünftig geregelt sind. Ich meckere manchmal, aber nur, damit der Laden läuft. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Gisela","text":"Helferin vom Bratwurststand Hallo, ich bin Gisela vom Bratwurststand gegenüber. Ich helfe gern, sage offen meine Meinung und finde meistens eine praktische Lösung, bevor aus einer Kleinigkeit ein großes Problem wird. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Kalle","text":"Rentner & Stammgast Tach zusammen, ich bin Kalle. Ich komme oft auf den Weihnachtsmarkt, kenne viele Leute und habe für fast jede Situation einen Spruch. Mir sind Freundlichkeit, Ordnung und ein bisschen Humor besonders wichtig. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Hannes","text":"Clubsprecher Hallo, ich bin Hannes, der Clubsprecher. Mir ist wichtig, dass Informationen verständlich weitergegeben werden, alle den gleichen Stand haben und der Köcheclub nach außen freundlich und verlässlich auftritt. Avatar Figur Begleitung","tip":""},{"kind":"academy","module":"","part":"Teil 2","section":"Figuren und Avatare","chapter":0,"title":"Detlef","text":"Kassenwart Guten Tag, ich bin Detlef, der Kassenwart. Mir sind nachvollziehbare Abläufe, ein sorgfältiger Umgang mit Geld und klare Absprachen besonders wichtig. Avatar Figur Begleitung","tip":""}];
